  RAISE EXCEPTION 'Spinach omelette historical identity/date preservation failed';
 END IF;
 IF outside_checksum IS DISTINCT FROM(SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) FROM public.recipes r WHERE r.recipe_group_id<>g)
  OR (SELECT count(*) FROM public.recipes WHERE language='es' AND published)<>es_count+1 THEN
  RAISE EXCEPTION 'Unexpected change outside spinachomelette group';
 END IF;
 RAISE NOTICE 'Spinach omelette verified7/7 within surrounding atomic lote03 transaction';
END
$spinachomelette$;
